    robj *o;
    long long start, end;
    long bit, strlen;
    unsigned char *p;
    char llbuf[LONG_STR_SIZE];
    int isbit = 0, end_given = 0;
    unsigned char first_byte_neg_mask = 0, last_byte_neg_mask = 0;

    /* Parse the bit argument to understand what we are looking for, set
     * or clear bits. */
    if (getLongFromObjectOrReply(c,c->argv[2],&bit,NULL) != C_OK)
        return;
    if (bit != 0 && bit != 1) {
        addReplyError(c, "The bit argument must be 1 or 0.");
        return;
    }

    /* If the key does not exist, from our point of view it is an infinite
     * array of 0 bits. If the user is looking for the first clear bit return 0,
     * If the user is looking for the first set bit, return -1. */
    if ((o = lookupKeyRead(c->db,c->argv[1])) == NULL) {
        if (bit) addReplyLongLong(c, -1);
        else addReply(c, shared.czero);
        return;
    }
    if (checkType(c,o,OBJ_STRING)) return;

    /* Read the string payload from the object's encoding and SDS header. */
    p = NULL;
    strlen = 0;
    if (o->encoding == OBJ_ENCODING_INT) {
        p = (unsigned char *) llbuf;
        strlen = ll2string(llbuf,LONG_STR_SIZE,(long)o->ptr);
    } else {
        sds s = o->ptr;
        unsigned char hdr_flags = s[-1];
        p = (unsigned char *) s;
        switch (hdr_flags & SDS_TYPE_MASK) {
        case SDS_TYPE_5:
            strlen = SDS_TYPE_5_LEN(hdr_flags);
            break;
        case SDS_TYPE_8:
            strlen = SDS_HDR(8,s)->len;
            break;
        case SDS_TYPE_16:
            strlen = SDS_HDR(16,s)->len;
            break;
        case SDS_TYPE_32:
            strlen = SDS_HDR(32,s)->len;
            break;
        default:
            strlen = SDS_HDR(64,s)->len;
            break;
        }
    }
    serverAssert(strlen <= server.proto_max_bulk_len);

    /* Parse start/end range if any. */
    if (c->argc == 4 || c->argc == 5 || c->argc == 6) {
        long long totlen = strlen;
        /* Make sure we will not overflow */
        serverAssert(totlen <= LLONG_MAX >> 3);
        if (getLongLongFromObjectOrReply(c,c->argv[3],&start,NULL) != C_OK)
            return;
        if (c->argc == 6) {
            if (!strcasecmp(c->argv[5]->ptr,"bit")) isbit = 1;
            else if (!strcasecmp(c->argv[5]->ptr,"byte")) isbit = 0;
            else {
                addReplyErrorObject(c,shared.syntaxerr);
                return;
            }
        }
        if (c->argc >= 5) {
            if (getLongLongFromObjectOrReply(c,c->argv[4],&end,NULL) != C_OK)
                return;
            end_given = 1;
        } else {
            if (isbit) end = (totlen<<3) + 7;
            else end = totlen-1;
        }
        if (isbit) totlen <<= 3;
        /* Convert negative indexes */
        if (start < 0) start = totlen+start;
        if (end < 0) end = totlen+end;
        if (start < 0) start = 0;
        if (end < 0) end = 0;
        if (end >= totlen) end = totlen-1;
        if (isbit && start <= end) {
            /* Before converting bit offset to byte offset, create negative masks
             * for the edges. */
            first_byte_neg_mask = ~((1<<(8-(start&7)))-1) & 0xFF;
            last_byte_neg_mask = (1<<(7-(end&7)))-1;
            start >>= 3;
            end >>= 3;
        }
    } else if (c->argc == 3) {
        /* The whole string. */
        start = 0;
        end = strlen-1;
    } else {
        /* Syntax error. */
        addReplyErrorObject(c,shared.syntaxerr);
        return;
    }

